What does this program print?

```cpp
#include <map>
#include <print>
#include <string>

int main() {
    std::map<std::string, int> m;
    m["pear"] = 3;
    m["apple"] = 5;
    m["fig"] = 1;
    m["apple"] += 2;
    for (const auto& [k, v] : m) std::print("{}{} ", k, v);
    std::println("");
}
```

What does this program print?

```cpp
#include <algorithm>
#include <print>
#include <vector>

int main() {
    std::vector<int> v{2, 4, 4, 4, 7, 9};
    auto lo = std::ranges::lower_bound(v, 4);
    auto hi = std::ranges::upper_bound(v, 4);
    std::println("{} {} {}", lo - v.begin(), hi - v.begin(), hi - lo);
}
```

The program below prints the values from a view pipeline, then `|`, then how many times the filter's predicate was called. What do you expect the **values** part to be? Type only the two numbers before the `|`.

```cpp
std::vector<int> v{3, 8, 1, 9, 4, 7};
int calls = 0;
auto odd = [&calls](int x) { ++calls; return x % 2 == 1; };
auto r = v | std::views::filter(odd)
           | std::views::transform([](int x) { return x * 10; })
           | std::views::take(2);
for (int x : r) std::print("{} ", x);
std::println("| {} calls", calls);
```

